def segment_bump(x,y,line,width):
    ax,ay,bx,by=line; vx,vy=bx-ax,by-ay; length=vx*vx+vy*vy
    t=np.clip(((x-ax)*vx+(y-ay)*vy)/length,0,1)
    dist=((x-(ax+t*vx))**2+(y-(ay+t*vy))**2)**.5
    return np.exp(-(dist/width)**2)*np.sin(np.pi*np.clip(t,.01,.99))

for spec in specs:
    ox,oy=spec['origin']; left,top,right,bottom=spec['crop']; cw,ch=right-left,bottom-top
    mask=Image.new('L',(cw,ch),0); draw=ImageDraw.Draw(mask)
    for pts in spec['parts'].values(): draw.polygon([(ox+x/2-left,oy+y/2-top) for x,y in pts],fill=255)
    # 原图本身不改色，只有轮廓掩码；半像素软边避免羽尖的锯齿。
    mask=mask.filter(ImageFilter.GaussianBlur(.38))
    texture=source.crop(spec['crop']).convert('RGBA');texture.putalpha(mask)
    texture.save(ASSETS/f"birds-{spec['name']}-approved.png")
    spec['texture']=f"birds-{spec['name']}-approved.png"
    spec['world_scale']=14.222222/W
    # 将观察坐标转换为原图像素；所有部件继续使用统一原图坐标与墙面锚点。
    spec['parts']={name:[[ox+x/2,oy+y/2] for x,y in pts] for name,pts in spec['parts'].items()}
    for key in ['body','head','shoulder']:
        x,y,rx,ry=spec[key];spec[key]=[ox+x/2,oy+y/2,rx/2,ry/2]
    for key in ['far_ridges','near_ridges','tail_ridges']:
        spec[key]=[[ox+ax/2,oy+ay/2,ox+bx/2,oy+by/2] for ax,ay,bx,by in spec[key]]

(DESIGN/'birds-contours.json').write_text(json.dumps({'source_size':[W,H],'birds':specs},indent=2),encoding='utf-8')
print('Prepared approved bird contours and source UV textures',source.size)
